import{_ as n,C as t,o as s,c as i,j as a,a as l,E as d,a5 as r}from"./chunks/framework.DtspaGiy.js";const f=JSON.parse('{"title":"Install","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md"}'),c={name:"guide/install.md"};function p(h,e,u,m,k,b){const o=t("DownloadButtons");return s(),i("div",null,[e[0]||(e[0]=a("h1",{id:"install",tabindex:"-1"},[l("Install "),a("a",{class:"header-anchor",href:"#install","aria-label":'Permalink to "Install"'},"​")],-1)),d(o),e[1]||(e[1]=r('<h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>Blank 3 needs macOS 12 (Monterey) or newer.</p><p>Blank is not notarized by Apple, so macOS blocks it the first time you open it. To allow it:</p><ul><li><strong>macOS 15 (Sequoia) or newer:</strong> try to open Blank once, then go to <strong>System Settings → Privacy &amp; Security</strong> and click <strong>Open Anyway</strong>.</li><li><strong>macOS 14 or older:</strong> right-click <code>blank.app</code> in Applications, choose <strong>Open</strong>, then confirm with <strong>Open</strong>.</li><li><strong>Terminal:</strong> run <code>xattr -dr com.apple.quarantine /Applications/blank.app</code>.</li></ul><details class="details custom-block"><summary>macOS says &quot;blank is damaged and can&#39;t be opened&quot;</summary><p>Blank v1.2.0 and older is not fully signed, so macOS does not offer <strong>Open Anyway</strong> for these versions. Only the Terminal command above works.</p></details><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>Download the <code>.msi</code> installer, or the <code>.exe</code> if you prefer a setup wizard. Both install the same app.</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><p>The easiest way is the <a href="https://snapcraft.io/blank" target="_blank" rel="noreferrer">Snap Store</a>, which keeps Blank up to date by itself and works on Ubuntu and most other distributions:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blank</span></span></code></pre></div><details class="details custom-block"><summary>How the Snap differs</summary><p>Snaps run in a sandbox that only sees part of your computer:</p><ul><li><code>Mod</code> <code>O</code>, <code>Mod</code> <code>Shift</code> <code>S</code> and the exports reach every file you pick.</li><li>From the terminal, <code>blank notes.md</code> opens files in your home folder, except in hidden folders like <code>~/.notes</code>. For USB drives and other disks, run <code>sudo snap connect blank:removable-media</code> once.</li><li>Its settings and saved document are separate from a <code>.deb</code>, <code>.rpm</code> or AppImage install. The config file is <code>~/snap/blank/current/.config/com.github.fpurchess.blank/blank.json</code>.</li></ul></details><p>The packages below need glibc 2.35 or newer and WebKitGTK 4.1, e.g. Ubuntu 22.04+ or Debian 12+.</p><ul><li><strong>Debian, Ubuntu:</strong> <code>sudo apt install ./blank_*_amd64.deb</code></li><li><strong>Fedora:</strong> <code>sudo dnf install ./blank-*.x86_64.rpm</code></li><li><strong>openSUSE:</strong> <code>sudo zypper install ./blank-*.x86_64.rpm</code></li><li><strong>Any distribution:</strong> make the AppImage executable with <code>chmod +x blank_*.AppImage</code> and run it. AppImages need FUSE 2, which newer Ubuntu releases don&#39;t install by default: <code>sudo apt install libfuse2t64</code> (Ubuntu 24.04+) or <code>libfuse2</code> (older).</li></ul><p>The <code>.deb</code> and <code>.rpm</code> put Blank in your app menu and in <strong>Open With</strong> for markdown and Word files. Right-click any <code>.md</code> file and choose <strong>Open With → Blank</strong>, or set it as the default app for markdown there and open your notes with a double-click. A <code>.docx</code> opens as a new markdown document and the Word file stays as it is, see <a href="./files#open-word-documents">Open a Word document</a>.</p><h2 id="open-a-file-from-the-terminal" tabindex="-1">Open a file from the terminal <a class="header-anchor" href="#open-a-file-from-the-terminal" aria-label="Permalink to &quot;Open a file from the terminal&quot;">​</a></h2><p>Pass one or more paths to open markdown files directly. Each opens in a tab; while Blank is running, they open as new tabs in its window rather than in a second one:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-IvFCk" id="tab-qxq2oeR" checked><label data-title="Linux" for="tab-qxq2oeR">Linux</label><input type="radio" name="group-IvFCk" id="tab-ZLaXehB"><label data-title="macOS" for="tab-ZLaXehB">macOS</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blank</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Documents/notes.md</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/Applications/blank.app/Contents/MacOS/blank</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Documents/notes.md</span></span></code></pre></div></div></div><p>With a path, <code>Mod</code> <code>S</code> saves to that file right away. Opening files from your file manager, with <strong>Open With</strong>, <code>xdg-open</code> or <code>open</code>, works the same way, and on macOS so does a double-click in Finder.</p><p>On Linux, Blank finds its running window through the session bus, which every desktop has. Without one, as in some minimal setups, each start opens a window of its own, and only the first remembers its tabs. On Wayland, the window may only flash in the taskbar instead of coming to the front.</p><p><code>blank --version</code> shows which version you have, and <code>blank --help</code> what you can pass, without opening a window.</p>',20))])}const y=n(c,[["render",p]]);export{f as __pageData,y as default};
